def rebase(input_base, digits, output_base):
    if input_base < 2:
        raise ValueError("input base must be >= 2")
    if output_base < 2:
        raise ValueError("output base must be >= 2")
    if any((not isinstance(d, int)) or d < 0 or d >= input_base for d in digits):
        raise ValueError("all digits must satisfy 0 <= d < input base")

    # Convert input digits to an integer value
    value = 0
    for d in digits:
        value = value * input_base + d

    # Special case for zero
    if value == 0:
        return [0]

    # Convert integer value to output base digits
    output_digits = []
    while value > 0:
        output_digits.append(value % output_base)
        value //= output_base

    return list(reversed(output_digits))
